// Drafted by Smithers from a prompt. In this form it runs on your device; other code needs a sandbox.
import { AgentAction } from "@smthrs/agent"
import { Flow } from "@smthrs/flow"
import { Schema } from "effect"

/** What the agent does each time the flow runs. */
const instructions = [
  "Open the Effect documentation for the person. Call app/web/open once, with the URL set to exactly https://effect.website/docs and mode \"embed\"; that shows the page inside the chat with its origin above it, which is exactly what this flow promises. Use that URL verbatim: no trailing slash, no anchor, no query, no different scheme. Never choose a different page on your own — do not open the root domain, another Effect documentation page, or a nearby site, and do not use mode \"tab\", which would only add an Open button card instead of showing the page. Do not ask the person for a URL or for approval; this flow takes no input. When the call succeeds, reply with one brief sentence pointing at the embedded page and stop. If the call fails, do not retry with an alternate or corrected URL; report briefly that the page did not open, quoting the error, and stop.",
].join("\n")

/** The flow's one step: the agent follows the instructions with the run's input. */
const Agent = AgentAction.make("open-effect-docs/agent", {
  payload: { input: Schema.String },
  output: Schema.String,
  seat: "agent",
  prompt: ({ input }) => (input === "" ? instructions : `${instructions}\n\nInput: ${input}`),
})

export default Flow.make("open-effect-docs", {
  description: "Open https://effect.website/docs so the Effect documentation appears in the chat as an embedded page, with its origin shown above it.",
  capabilities: [],
  flows: ["app/web/open"],
  payload: { input: Schema.String },
  success: Schema.String,
  error: Agent.errorSchema,
  body: ({ input }) => Agent.call({ input }),
})
